create table CHB_AGENCY_DEPLOY(
INSIDE_CODE VARCHAR(30)  comment '代销商内部TCODE',
MAP_CNAME   VARCHAR(200) comment '映射中文名称',
MAP_CODE    VARCHAR(30) comment '映射值CODE',
FUND_ACC_PLACE  VARCHAR(30) comment '关联账号开户所在地(默认值)',
BANK_REGULATION  VARCHAR(30) comment '待销机构所属银监机构',
TRADE_TEELER  VARCHAR(30) comment '交易柜员',
BANK_BUSI_PLACE  VARCHAR(30) comment '业务发生地所属银监(默认值)',
CHANNEL  VARCHAR(30) comment '渠道',
UPDATE_USER varchar(20) null comment '更新人',
UPDATE_TIME datetime null comment '更新时间',
CREATE_USER varchar(32) null comment '创建人',
CREATE_TIME datetime null comment '创建时间'
);
delete from  CHB_AGENCY_DEPLOY;
